import torch

def run(grad_in, input_sizes, dim, size, step):
    return torch.ops.aten.unfold_backward(
        grad_in, input_sizes, dim, size, step
    )


def run_correctness(grad_in, input_sizes, dim, size, step):
    output = torch.ops.aten.unfold_backward(
        grad_in.float(), input_sizes, dim, size, step
    )
    return output.to(grad_in.dtype)
